// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        address prevOwner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        if (actor != address(this)) {
            assertTrue(c.owner() == prevOwner, "non-admin changed owner");
        } else {
            assertTrue(true);
        }
    }
}
